import { loadCatalogMemoized } from "./lib/pricing.js";
import { SessionMetricsStore } from "./lib/metrics-store.js";
import { ConfigSchema } from "./config.js";
import { createCommand } from "./command.js";
import { Sidebar } from "./components/sidebar.js";
import { createComponent } from "@opentui/solid";
//#region src/plugin.tsx
async function tui(api, options, _meta) {
	const config = ConfigSchema.parse(options ?? {});
	const store = new SessionMetricsStore(api, { includeSubagents: config.include_subagents });
	api.keymap.registerLayer({ commands: [createCommand(api, config, store)] });
	api.slots.register({
		order: 150,
		slots: { sidebar_content(_ctx, props) {
			return createComponent(Sidebar, {
				api,
				get session_id() {
					return props.session_id;
				},
				config,
				store
			});
		} }
	});
	if (config.context.show) api.plugins.deactivate("internal:sidebar-context");
	api.lifecycle.onDispose(() => store.dispose());
	loadCatalogMemoized().then((catalog) => {
		store.setCatalog(catalog);
		store.refreshAll();
	});
}
var plugin_default = {
	id: "session-metrics",
	tui
};
//#endregion
export { plugin_default as default };
